SELECT "brokerid", "managerid", "firstname", "lastname", "middleinitial", "branch", "office", "phone", "iscurrent", "batchid", "effectivedate", "enddate", CAST(ROW_NUMBER() OVER (ORDER BY brokerid) AS int) AS "sk_brokerid" FROM (SELECT TRY_CAST((CAST(h.EmployeeID AS INT)) AS int) AS "brokerid", TRY_CAST((CAST(h.ManagerID AS INT)) AS int) AS "managerid", TRY_CAST((CAST(h.EmployeeFirstName AS CHAR(50))) AS char(50)) AS "firstname", TRY_CAST((CAST(h.EmployeeLastName AS CHAR(50))) AS char(50)) AS "lastname", TRY_CAST((CAST(h.EmployeeMI AS CHAR(1))) AS char(1)) AS "middleinitial", TRY_CAST((CAST(h.EmployeeBranch AS CHAR(50))) AS char(50)) AS "branch", TRY_CAST((CAST(h.EmployeeOffice AS CHAR(50))) AS char(50)) AS "office", TRY_CAST((CAST(h.EmployeePhone AS CHAR(14))) AS char(14)) AS "phone", TRY_CAST((CAST(TRUE AS BOOLEAN)) AS boolean) AS "iscurrent", TRY_CAST((CAST(NULL AS INTEGER)) AS int) AS "batchid", TRY_CAST((CAST(NULL AS DATE)) AS date) AS "effectivedate", TRY_CAST((CAST('9999-12-31' AS DATE)) AS date) AS "enddate" FROM HR AS h)
